scenarios.source:
model User {
  id    String  @id @default(cuid())
  email String  @unique
  name  String?
}

scenarios.output:
const users = await avClient.User.find.many({
  select: ["id", "name"],
  limit: 3,
});

scenarios.source:
model Post {
  id        String  @id @default(cuid())
  title     String
  published Boolean @default(false)
}

scenarios.output:
const posts = await avClient.Post.find.many({
  where: { published: true },
  select: ["id", "title"],
});

